CREATE OR REPLACE FUNCTION "public"."fn_admin_incoherences_identite"() RETURNS TABLE("soignant_id" "uuid", "prenom" "text", "nom" "text", "prenom_profil" "text", "nom_profil" "text", "nom_rpps" "text", "nom_cni" "text", "coherence_identite" "text", "coherence_details" "jsonb", "rpps_verifie" boolean, "identite_verifiee" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NOT est_admin() THEN RETURN; END IF;
    RETURN QUERY
    SELECT
      s.id,
      s.prenom::TEXT,
      s.nom::TEXT,
      s.prenom::TEXT AS prenom_profil,
      s.nom::TEXT AS nom_profil,
      (s.coherence_details->>'nom_rpps')::TEXT,
      (s.coherence_details->>'nom_cni')::TEXT,
      s.coherence_identite,
      s.coherence_details,
      s.rpps_verifie,
      s.identite_verifiee
    FROM soignants s
    WHERE s.coherence_identite = 'INCOHERENT'
    AND s.supprime_le IS NULL
    ORDER BY s.modifie_le DESC;
END;
$$;


