CREATE OR REPLACE FUNCTION "public"."fn_auto_terminer_missions"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INT;
BEGIN
    UPDATE missions
    SET statut = 'TERMINEE',
        modifie_le = now()
    WHERE statut = 'EN_COURS'
    AND fin_le < now() - INTERVAL '15 minutes'; -- petite marge pour éviter les race conditions
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN jsonb_build_object('success', true, 'missions_terminees', v_count);
END;
$$;


