CREATE OR REPLACE FUNCTION "public"."fn_get_stripe_account_soignant"("p_soignant_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_account TEXT;
BEGIN
    SELECT stripe_account_id INTO v_account FROM stripe_connect_onboarding
    WHERE soignant_id = p_soignant_id AND onboarding_complete = TRUE AND statut = 'COMPLET';
    RETURN v_account;
END;
$$;


ALTER FUNCTION "public"."fn_get_stripe_account_soignant"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_haversine_distance_m"("p_lat1" numeric, "p_lng1" numeric, "p_lat2" numeric, "p_lng2" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  v_r constant numeric := 6371000;
  v_phi1 numeric; v_phi2 numeric; v_dphi numeric; v_dlambda numeric;
  v_a numeric; v_c numeric;
BEGIN
  IF p_lat1 IS NULL OR p_lng1 IS NULL OR p_lat2 IS NULL OR p_lng2 IS NULL THEN RETURN NULL; END IF;
  v_phi1 := radians(p_lat1); v_phi2 := radians(p_lat2);
  v_dphi := radians(p_lat2 - p_lat1); v_dlambda := radians(p_lng2 - p_lng1);
  v_a := sin(v_dphi/2) * sin(v_dphi/2) + cos(v_phi1) * cos(v_phi2) * sin(v_dlambda/2) * sin(v_dlambda/2);
  v_c := 2 * atan2(sqrt(v_a), sqrt(1 - v_a));
  RETURN round(v_r * v_c);
END;
$$;


ALTER FUNCTION "public"."fn_haversine_distance_m"("p_lat1" numeric, "p_lng1" numeric, "p_lat2" numeric, "p_lng2" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_health_check"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_soignants INTEGER;
    v_missions INTEGER;
    v_dernier_audit TIMESTAMPTZ;
BEGIN
    SELECT COUNT(*) INTO v_soignants FROM soignants WHERE supprime_le IS NULL;
    SELECT COUNT(*) INTO v_missions FROM missions WHERE statut = 'OUVERTE';
    SELECT MAX(cree_le) INTO v_dernier_audit FROM journaux_audit;

    INSERT INTO health_check (service, statut, details)
    VALUES ('API', 'OK', jsonb_build_object(
        'soignants_actifs', v_soignants,
        'missions_ouvertes', v_missions,
        'dernier_audit', v_dernier_audit,
        'timestamp', NOW()
    ));

    RETURN jsonb_build_object(
        'status', 'OK',
        'soignants', v_soignants,
        'missions_ouvertes', v_missions,
        'dernier_audit', v_dernier_audit
    );
END;
$$;


ALTER FUNCTION "public"."fn_health_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_html_escape"("p_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN REPLACE(REPLACE(REPLACE(REPLACE(
        COALESCE(p_text, ''),
        '&', '&amp;'),
        '<', '&lt;'),
        '>', '&gt;'),
        '"', '&quot;');
    -- Apostrophes intentionnellement non encodées
END;
$$;


ALTER FUNCTION "public"."fn_html_escape"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_init_proprietaire_etab"("p_etablissement_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_uid uuid;
  v_membre_id uuid;
BEGIN
  IF v_caller IS NULL THEN
    -- Appel serveur (register-etablissement en service_role)
    v_uid := p_user_id;
    IF v_uid IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
    END IF;
  ELSE
    -- Appel client authentifié : on ignore p_user_id et on vérifie la revendication
    v_uid := v_caller;
    IF NOT (
      est_admin()
      OR EXISTS (
        SELECT 1 FROM auth.users u
        WHERE u.id = v_caller
          AND (u.raw_app_meta_data ->> 'etablissement_id') = p_etablissement_id::text
      )
    ) THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.membres_etablissement
    WHERE etablissement_id = p_etablissement_id AND actif = true
  ) THEN
    RETURN jsonb_build_object('success', true, 'message', 'Membres déjà présents');
  END IF;

  INSERT INTO public.membres_etablissement (
    etablissement_id, user_id, role, accepte_le, actif
  ) VALUES (
    p_etablissement_id, v_uid, 'PROPRIETAIRE', now(), true
  )
  RETURNING id INTO v_membre_id;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_ETABLISSEMENT', 'MODIFICATION_PROFIL', 'membre_etablissement', v_membre_id,
    jsonb_build_object(
      'evenement', 'PROPRIETAIRE_INITIALISE',
      'etablissement_id', p_etablissement_id
    )
  );

  RETURN jsonb_build_object('success', true, 'membre_id', v_membre_id);
END;
$$;


ALTER FUNCTION "public"."fn_init_proprietaire_etab"("p_etablissement_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_initialiser_preferences_matching"("p_pref_nuit" numeric, "p_pref_jour" numeric, "p_pref_weekend" numeric, "p_pref_semaine" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;
  IF p_pref_nuit NOT BETWEEN 0 AND 1 OR p_pref_jour NOT BETWEEN 0 AND 1
     OR p_pref_weekend NOT BETWEEN 0 AND 1 OR p_pref_semaine NOT BETWEEN 0 AND 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Préférences hors bornes [0,1]');
  END IF;

  INSERT INTO public.matching_preferences_soignant
    (soignant_id, pref_nuit, pref_jour, pref_weekend, pref_semaine, nb_signaux, maj_le)
  VALUES (v_uid, p_pref_nuit, p_pref_jour, p_pref_weekend, p_pref_semaine, 0, now())
  ON CONFLICT (soignant_id) DO UPDATE SET
    pref_nuit = EXCLUDED.pref_nuit,
    pref_jour = EXCLUDED.pref_jour,
    pref_weekend = EXCLUDED.pref_weekend,
    pref_semaine = EXCLUDED.pref_semaine,
    maj_le = now()
  WHERE matching_preferences_soignant.nb_signaux = 0;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_initialiser_preferences_matching"("p_pref_nuit" numeric, "p_pref_jour" numeric, "p_pref_weekend" numeric, "p_pref_semaine" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_inscrire_liste_attente_prevoyance"("p_email" "text", "p_niveau" "text" DEFAULT 'INDIFFERENT'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_uid UUID := auth.uid();
  v_email_clean TEXT;
  v_niveau public.niveau_prevoyance_souhaite;
  v_id UUID;
  v_existing UUID;
BEGIN
  v_email_clean := LOWER(TRIM(COALESCE(p_email, '')));
  IF v_email_clean = '' OR v_email_clean !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email invalide');
  END IF;

  BEGIN
    v_niveau := COALESCE(UPPER(TRIM(p_niveau)), 'INDIFFERENT')::public.niveau_prevoyance_souhaite;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Niveau invalide (BRONZE/ARGENT/OR/INDIFFERENT)');
  END;

  SELECT id INTO v_existing FROM prevoyance_liste_attente WHERE email = v_email_clean;
  IF v_existing IS NOT NULL THEN
    UPDATE prevoyance_liste_attente
    SET niveau_souhaite = v_niveau,
        soignant_id = COALESCE(v_uid, soignant_id),
        mis_a_jour_le = NOW()
    WHERE id = v_existing
    RETURNING id INTO v_id;
  ELSE
    INSERT INTO prevoyance_liste_attente (soignant_id, email, niveau_souhaite)
    VALUES (v_uid, v_email_clean, v_niveau)
    RETURNING id INTO v_id;
  END IF;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := COALESCE(v_uid, v_id),
    p_type_acteur := CASE WHEN v_uid IS NULL THEN 'SYSTEME' ELSE 'SOIGNANT' END,
    p_action := 'INSCRIPTION_LISTE_ATTENTE_PREVOYANCE',
    p_type_ressource := 'prevoyance_liste_attente',
    p_id_ressource := v_id,
    p_details := jsonb_build_object('email', v_email_clean, 'niveau', v_niveau::text, 'updated', v_existing IS NOT NULL)
  );

  RETURN jsonb_build_object(
    'success', true,
    'id', v_id,
    'updated', v_existing IS NOT NULL,
    'message', 'Vous êtes inscrit·e sur la liste d''attente. Vous serez prévenu·e dès le lancement.'
  );
END;
$_$;


ALTER FUNCTION "public"."fn_inscrire_liste_attente_prevoyance"("p_email" "text", "p_niveau" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_inviter_membre_etab"("p_email" "text", "p_role" "text", "p_etablissement_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid;
  v_invitation_id uuid;
  v_token text;
  v_perms jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  IF p_role NOT IN ('ADMIN_GROUPE', 'RH', 'POINTAGE_ONLY', 'LECTURE_SEULE') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'ROLE_INVALIDE');
  END IF;

  IF p_email IS NULL OR length(trim(p_email)) = 0 OR p_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'EMAIL_INVALIDE');
  END IF;

  v_etab_id := COALESCE(p_etablissement_id, public.mon_etablissement_id());

  -- Vérif autorisation : seul PROPRIETAIRE peut inviter
  SELECT public.fn_mes_permissions_etab(v_etab_id) INTO v_perms;
  IF NOT COALESCE((v_perms->'permissions'->>'gerer_equipe')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE',
                                'error', 'Seul un PROPRIETAIRE peut inviter des membres');
  END IF;

  -- Pas déjà membre actif
  IF EXISTS (
    SELECT 1 FROM public.membres_etablissement m
    JOIN auth.users u ON u.id = m.user_id
    WHERE m.etablissement_id = v_etab_id
      AND lower(u.email) = lower(trim(p_email))
      AND m.actif = true
  ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DEJA_MEMBRE');
  END IF;

  -- Pas déjà invité en attente
  IF EXISTS (
    SELECT 1 FROM public.invitations_etablissement
    WHERE etablissement_id = v_etab_id
      AND lower(email_invite) = lower(trim(p_email))
      AND statut = 'EN_ATTENTE'
      AND expire_le > now()
  ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'INVITATION_DEJA_EN_ATTENTE');
  END IF;

  INSERT INTO public.invitations_etablissement (
    etablissement_id, email_invite, role_propose, invite_par
  ) VALUES (
    v_etab_id, lower(trim(p_email)), p_role, v_uid
  )
  RETURNING id, token INTO v_invitation_id, v_token;

  -- Audit
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_ETABLISSEMENT', 'MODIFICATION_PROFIL', 'invitation_etab', v_invitation_id,
    jsonb_build_object(
      'evenement', 'INVITATION_MEMBRE_CREEE',
      'email', lower(trim(p_email)),
      'role', p_role,
      'etablissement_id', v_etab_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'invitation_id', v_invitation_id,
    'token', v_token,
    'expire_le', (now() + INTERVAL '7 days')
  );
END;
$_$;


ALTER FUNCTION "public"."fn_inviter_membre_etab"("p_email" "text", "p_role" "text", "p_etablissement_id" "uuid") OWNER TO "postgres";


