CREATE OR REPLACE FUNCTION "public"."fn_lister_factures_a_regenerer"("p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "numero_facture" "text", "type_document" "public"."type_document_facture", "soignant_id" "uuid", "cree_le" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT f.id, f.numero_facture, f.type_document, f.soignant_id, f.cree_le
    FROM public.factures_honoraires f
   WHERE f.pdf_a_regenerer = TRUE
     AND f.statut IN ('BROUILLON', 'EMISE')
     AND f.modifie_le < NOW() - INTERVAL '1 hour'
   ORDER BY f.cree_le ASC
   LIMIT p_limit;
$$;


