    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    DELETE FROM tokens_push
    WHERE derniere_utilisation < NOW() - INTERVAL '90 days'
       OR actif = FALSE;
