    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM fn_calculer_tous_documents_valides(COALESCE(NEW.soignant_id, OLD.soignant_id));
  RETURN COALESCE(NEW, OLD);
END;
