CREATE OR REPLACE FUNCTION "public"."fn_recalculer_tous_paliers"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab RECORD;
    v_count INTEGER := 0;
BEGIN
    FOR v_etab IN
        SELECT DISTINCT COALESCE(groupe_sante_id::TEXT, id::TEXT) AS cle_unique, id
        FROM etablissements
        WHERE supprime_le IS NULL
    LOOP
        PERFORM fn_recalculer_palier_commission(v_etab.id);
        v_count := v_count + 1;
    END LOOP;
    RETURN v_count;
END;
$$;


