CREATE OR REPLACE FUNCTION "public"."fn_trg_auto_commission_facturee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.facture_id IS NOT NULL AND (OLD.facture_id IS NULL OR OLD.facture_id != NEW.facture_id) THEN
        NEW.commission_facturee := true;
    END IF;
    RETURN NEW;
END;
$$;


