    IF TG_OP = 'INSERT' OR NEW.statut IS DISTINCT FROM OLD.statut THEN
      PERFORM public.fn_calculer_score_fiabilite_v2(NEW.soignant_id, 'engagement_urgence');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


