    "rib_ia_resultat" "jsonb",
    "rib_ia_coherent" boolean,
    "rib_ia_verifie_le" timestamp with time zone,
    "utm_source" "text",
    "utm_medium" "text",
    "utm_campaign" "text",
    "utm_content" "text",
