    CONSTRAINT "etablissements_formule_abonnement_check" CHECK (("formule_abonnement" = ANY (ARRAY['GRATUIT'::"text", 'STARTER'::"text", 'PRO'::"text", 'ENTERPRISE'::"text"]))),
    CONSTRAINT "etablissements_jour_paie_check" CHECK ((("jour_paie_habituel" >= 1) AND ("jour_paie_habituel" <= 31))),
    CONSTRAINT "etablissements_mode_facturation_check" CHECK (("mode_facturation" = ANY (ARRAY['PAR_MISSION'::"text", 'MENSUEL'::"text"]))),
    CONSTRAINT "etablissements_mode_paiement_commission_check" CHECK (("mode_paiement_commission" = ANY (ARRAY['STRIPE_RESERVATION'::"text", 'FACTURE_MENSUELLE'::"text", 'SEPA_DEBIT'::"text", 'CHORUS_PRO'::"text"]))),
    CONSTRAINT "etablissements_rattachement_methode_check" CHECK ((("rattachement_methode" IS NULL) OR ("rattachement_methode" = ANY (ARRAY['AUTO_DIRIGEANT'::"text", 'EMAIL_PRO'::"text", 'ADMIN'::"text"])))),
    CONSTRAINT "etablissements_representant_piece_type_check" CHECK ((("representant_piece_type_document" IS NULL) OR ("representant_piece_type_document" = ANY (ARRAY['CARTE_IDENTITE'::"text", 'PASSEPORT'::"text", 'TITRE_SEJOUR'::"text"])))),
    CONSTRAINT "etablissements_statut_verification_check" CHECK (("statut_verification" = ANY (ARRAY['EN_ATTENTE'::"text", 'EN_COURS'::"text", 'VERIFIE'::"text", 'REJETE'::"text", 'SUSPENDU'::"text"]))),
    CONSTRAINT "etablissements_tolerance_pointage_m_check" CHECK ((("tolerance_pointage_m" >= 30) AND ("tolerance_pointage_m" <= 1000)))
);

ALTER TABLE ONLY "public"."etablissements" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."etablissements" OWNER TO "postgres";


COMMENT ON COLUMN "public"."etablissements"."convention_collective" IS 'Convention collective applicable (texte libre IDCC + libellé, ex. "IDCC 0029 - Hospitalisation privée"). Mention obligatoire bulletin de paie art. R3243-1 CTW.';



COMMENT ON COLUMN "public"."etablissements"."bloque_auto_le" IS 'CP-C-3 : date blocage auto pour retards paiement soignant ou facture commission >45j. NULL = non bloque.';



COMMENT ON COLUMN "public"."etablissements"."bloque_auto_raisons" IS 'CP-C-3 : snapshot JSONB au moment du blocage.';



COMMENT ON COLUMN "public"."etablissements"."contrat_service_signe" IS 'True si l''établissement a signé le contrat de service Jolene (obligatoire pour publier des missions).';



COMMENT ON COLUMN "public"."etablissements"."rib_s3_key" IS 'Clé S3 du RIB uploadé dans le bucket etablissement-documents. Obligatoire pour publier des missions.';



COMMENT ON COLUMN "public"."etablissements"."tolerance_pointage_m" IS 'Tolérance pointage GPS en mètres. Default 100m (urbain). Range 30 (cabinet médical précis) - 1000 (zone rurale étendue). Si l''étab utilise le QR code (recommandé), cette valeur sert uniquement d''alerte admin si écart anormal détecté lors du scan GPS background.';



COMMENT ON COLUMN "public"."etablissements"."coherence_identite" IS 'Cohérence nom déclaré ↔ raison sociale SIRET/FINESS, calculée à l''inscription : OK / PARTIEL / INCOHERENT / NULL (non calculée, legacy).';



COMMENT ON COLUMN "public"."etablissements"."est_compte_test" IS 'Établissement e2e Playwright ou d''audit interne — ses missions sont invisibles pour les vrais soignants.';



