CREATE TABLE IF NOT EXISTS "public"."litiges" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "presence_id" "uuid",
    "mission_id" "uuid" NOT NULL,
    "soignant_id" "uuid" NOT NULL,
    "etablissement_id" "uuid" NOT NULL,
    "initie_par" "text" NOT NULL,
    "motif" "text" NOT NULL,
    "reponse" "text",
    "statut" "text" DEFAULT 'OUVERT'::"text",
    "resolu_par" "uuid",
    "resolution" "text",
    "cree_le" timestamp with time zone DEFAULT "now"(),
    "resolu_le" timestamp with time zone,
    "accord_soignant" boolean DEFAULT false,
    "accord_etablissement" boolean DEFAULT false,
    "accord_soignant_le" timestamp with time zone,
    "accord_etablissement_le" timestamp with time zone,
    "paiement_soignant_id" "uuid",
    "type_litige" "public"."type_litige" DEFAULT 'AUTRE'::"public"."type_litige" NOT NULL,
    "categorie_litige" "public"."categorie_litige" DEFAULT 'AUTRE'::"public"."categorie_litige" NOT NULL,
    "facture_id" "uuid",
    "est_informatif" boolean DEFAULT false NOT NULL,
    "type_legacy" boolean DEFAULT false NOT NULL,
    "montant_tresorerie_bloquee" numeric(12,2),
    "derniers_rappels_envoyes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "escalade_auto_le" timestamp with time zone,
    "escalade_auto_motif" "text",
    "gel_facture_scope" "text" DEFAULT 'MISSION_ENTIERE'::"text" NOT NULL,
    "periode_debut" "date",
    "periode_fin" "date",
    "payload_modifications" "jsonb",
    "modifications_executees" boolean DEFAULT false NOT NULL,
    "modifications_executees_a" timestamp with time zone,
    "modifications_executees_par" "uuid",
    CONSTRAINT "litiges_gel_facture_scope_check" CHECK (("gel_facture_scope" = ANY (ARRAY['MISSION_ENTIERE'::"text", 'FACTURE_UNIQUE'::"text", 'AUCUN'::"text", 'PERIODE_LITIGIEUSE'::"text"]))),
    CONSTRAINT "litiges_initie_par_check" CHECK (("initie_par" = ANY (ARRAY['SOIGNANT'::"text", 'ETABLISSEMENT'::"text", 'SYSTEME'::"text"]))),
    CONSTRAINT "litiges_statut_check" CHECK (("statut" = ANY (ARRAY['OUVERT'::"text", 'EN_DISCUSSION'::"text", 'EN_MEDIATION'::"text", 'RESOLU_SOIGNANT'::"text", 'RESOLU_ETABLISSEMENT'::"text", 'RESOLU_ADMIN'::"text", 'FERME'::"text", 'MEDIATION_EN_COURS'::"text", 'RESOLU_ACCORD_PARTIES'::"text", 'REVUE_ADMIN'::"text", 'RESOLU_FAVEUR_SOIGNANT'::"text", 'RESOLU_FAVEUR_ETAB'::"text", 'RESOLU_PARTAGE'::"text"])))
);

ALTER TABLE ONLY "public"."litiges" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."litiges" OWNER TO "postgres";


COMMENT ON COLUMN "public"."litiges"."initie_par" IS 'CP-LITIGES-7a FIX 12 — origine de l''ouverture du litige : SOIGNANT (action manuelle soignant), ETABLISSEMENT (action manuelle établissement), SYSTEME (auto-création par fn_auto_creation_litiges_presence sur ABSENCE / DEPART_ANTICIPE / RETARD_IMPORTANT).';



COMMENT ON COLUMN "public"."litiges"."type_litige" IS 'Type fin parmi 12 valeurs. AUTRE par défaut.';



COMMENT ON COLUMN "public"."litiges"."categorie_litige" IS 'Catégorie de regroupement. Auto-synchronisée depuis type_litige via trigger.';



COMMENT ON COLUMN "public"."litiges"."facture_id" IS 'FK facture impactée par le litige. Nullable.';



COMMENT ON COLUMN "public"."litiges"."est_informatif" IS 'TRUE si litige hors fenêtre légale (> 6 mois).';



COMMENT ON COLUMN "public"."litiges"."type_legacy" IS 'TRUE pour litiges créés avant typologie.';



COMMENT ON COLUMN "public"."litiges"."montant_tresorerie_bloquee" IS 'Cache calculé : SUM(montant_ht) des factures gelées.';



COMMENT ON COLUMN "public"."litiges"."derniers_rappels_envoyes" IS 'Idempotence rappels cron.';



COMMENT ON COLUMN "public"."litiges"."escalade_auto_le" IS 'Timestamp de l escalade automatique.';



COMMENT ON COLUMN "public"."litiges"."escalade_auto_motif" IS 'Motif textuel de l escalade.';



COMMENT ON COLUMN "public"."litiges"."gel_facture_scope" IS 'Granularité du gel des factures lors d''ouverture du litige. MISSION_ENTIERE (défaut, gel global), FACTURE_UNIQUE (gel uniquement de la facture pointée par facture_id), AUCUN (pas de gel — litige informatif). Une 4e valeur PERIODE_LITIGIEUSE sera ajoutée avec la Partie 2 facturation hebdomadaire.';



COMMENT ON COLUMN "public"."litiges"."periode_debut" IS 'Partie 2 T9 : début de la période litigieuse (pour gel par chevauchement de factures hebdo). NULL si le litige porte sur la mission entière.';



COMMENT ON COLUMN "public"."litiges"."periode_fin" IS 'Partie 2 T9 : fin de la période litigieuse. NULL si mission entière.';



COMMENT ON COLUMN "public"."litiges"."payload_modifications" IS 'Payload JSON structuré décrivant les modifications convenues en cas d''accord avec changement de données aval (heures, montant, annulation, compensation). Structure : { type, modifications: {...}, justification }. Cf. docs/LITIGES_RESOLUTION_AUTOMATIQUE.md.';



