CREATE TABLE IF NOT EXISTS "public"."pauses_presence" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "presence_id" "uuid" NOT NULL,
    "soignant_id" "uuid" NOT NULL,
    "debut_le" timestamp with time zone DEFAULT "now"() NOT NULL,
    "fin_le" timestamp with time zone,
    "duree_min" numeric GENERATED ALWAYS AS (
CASE
    WHEN ("fin_le" IS NOT NULL) THEN "round"((EXTRACT(epoch FROM ("fin_le" - "debut_le")) / (60)::numeric), 2)
    ELSE NULL::numeric
END) STORED,
    "motif" "text" DEFAULT 'DEJEUNER'::"text",
    "cree_le" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "pauses_presence_motif_check" CHECK (("motif" = ANY (ARRAY['DEJEUNER'::"text", 'REPOS'::"text", 'PERSONNEL'::"text", 'AUTRE'::"text"])))
);


